// Inferencia inteira: entrada int8 [15] -> logits int32 [4]
static inline void gesture_inference(const int8_t *in, int32_t *logits){
  int32_t h[N_HIDDEN];
  for(int j=0;j<N_HIDDEN;j++){ int32_t acc=B1_INT32[j];
    for(int i=0;i<N_FEATURES;i++) acc+=(int32_t)in[i]*(int32_t)W1_INT8[i*N_HIDDEN+j];
    h[j]=acc>0?acc:0; }
  for(int k=0;k<N_CLASSES;k++){ int32_t acc=B2_INT32[k];
    for(int j=0;j<N_HIDDEN;j++) acc+=h[j]*(int32_t)W2_INT8[j*N_CLASSES+k];
    logits[k]=acc; } }
static inline int gesture_argmax(const int32_t *l){int b=0;for(int k=1;k<N_CLASSES;k++)if(l[k]>l[b])b=k;return b;}
